class SnapshotArray {
    arr;
    i = 0;
    constructor(length) {
        this.arr = Array.from({ length }, () => []);
    }
    set(index, val) {
        this.arr[index].push([this.i, val]);
    }
    snap() {
        return this.i++;
    }
    get(index, snap_id) {
        let [l, r] = [0, this.arr[index].length];
        while (l < r) {
            const mid = (l + r) >> 1;
            if (this.arr[index][mid][0] > snap_id) {
                r = mid;
            }
            else {
                l = mid + 1;
            }
        }
        --l;
        return l < 0 ? 0 : this.arr[index][l][1];
    }
}
